/** Convert the contract's reward units to decimal amounts of full Whale Passes. */
export function formatWhalePassAmount(halfPassValue) {
  let halfPasses = 0n;
  try { halfPasses = BigInt(halfPassValue || 0); } catch { /* invalid amount */ }
  if (halfPasses < 0n) halfPasses = 0n;
  const wholePasses = halfPasses / 2n;
  const hasHalf = halfPasses % 2n === 1n;
  return `${wholePasses}${hasHalf ? '.5' : ''}`;
}

export function formatWhalePassAward(halfPassValue) {
  const amount = formatWhalePassAmount(halfPassValue);
  const singular = amount === '1' || amount === '0.5';
  return `${amount} whale pass${singular ? '' : 'es'}`;
}
